import React, { useEffect } from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { Toaster } from 'react-hot-toast';
import { checkAuth, setSession } from './store/slices/authSlice';
import { supabase } from './services/authentication';

// Layout Components
import Navbar from './components/layout/Navbar';
import Footer from './components/layout/Footer';
import ProtectedRoute from './components/auth/ProtectedRoute';
import LoadingSpinner from './components/ui/LoadingSpinner';
import DatabaseStatus from './components/ui/DatabaseStatus';
import MobileNav from './components/layout/MobileNav';
// import AuthDebug from './components/debug/AuthDebug'; // Removed debug component

// Public Pages
import Home from './pages/public/Home';
import About from './pages/public/About';
import HowItWorks from './pages/public/HowItWorks';
import Pricing from './pages/public/Pricing';
import SuccessStories from './pages/public/SuccessStories';
import Login from './pages/auth/Login';
import Register from './pages/auth/Register';
import ForgotPassword from './pages/auth/ForgotPassword';

// Legal Pages
import TermsAndConditions from './pages/legal/TermsAndConditions';
import PrivacyPolicy from './pages/legal/PrivacyPolicy';
import TermsOfService from './pages/legal/TermsOfService';
import CookiesPolicy from './pages/legal/CookiesPolicy';

// Support Pages
import HelpCenter from './pages/support/HelpCenter';
import ContactUs from './pages/support/ContactUs';

// Worker Pages
import WorkerDashboard from './pages/worker/Dashboard';
import TaskBrowser from './pages/worker/TaskBrowser';
import TaskDetail from './pages/worker/TaskDetail';
import MySubmissions from './pages/worker/MySubmissions';

// Employer Pages
import EmployerDashboard from './pages/employer/Dashboard';
import CreateTask from './pages/employer/CreateTask';
import MyTasks from './pages/employer/MyTasks';
import ReviewSubmissions from './pages/employer/ReviewSubmissions';

// Shared Pages
import Wallet from './pages/shared/Wallet';
import Profile from './pages/shared/Profile';
import Settings from './pages/shared/Settings';

// Admin Pages
import AdminDashboard from './pages/admin/Dashboard';
import UserManagement from './pages/admin/UserManagement';
import TaskManagement from './pages/admin/TaskManagement';
import PaymentManagement from './pages/admin/PaymentManagement';

function App() {
  const dispatch = useDispatch();
  const { profile, isAuthenticated, loading } = useSelector((state) => state.auth);

  useEffect(() => {
    // Initialize authentication

    // Get initial session
    supabase.auth.getSession().then(({ data: { session } }) => {
      dispatch(setSession({ user: session?.user, session }));
      if (session?.user) {
        dispatch(checkAuth());
      }
    });

    // Listen for auth changes
    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((_event, session) => {
      dispatch(setSession({ user: session?.user, session }));
      if (session?.user) {
        dispatch(checkAuth());
      }
    });

    return () => subscription.unsubscribe();
  }, [dispatch]);

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <LoadingSpinner size="lg" />
      </div>
    );
  }

  // Check if we're in demo mode
  const isDemoMode = !process.env.REACT_APP_SUPABASE_URL || 
    process.env.REACT_APP_SUPABASE_URL.includes('demo-project');

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      <Navbar />
      
      {/* Demo Mode Banner */}
      {isDemoMode && (
        <div className="bg-yellow-50 border-b border-yellow-200 px-4 py-3">
          <div className="max-w-7xl mx-auto flex items-center justify-between">
            <div className="flex items-center">
              <div className="flex-shrink-0">
                <svg className="h-5 w-5 text-yellow-400" viewBox="0 0 20 20" fill="currentColor">
                  <path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                </svg>
              </div>
              <div className="ml-3">
                <p className="text-sm text-yellow-800">
                  <strong>Demo Mode:</strong> You're viewing a demonstration version. 
                  Use <code className="bg-yellow-100 px-1 rounded">demo@worker.com</code>, <code className="bg-yellow-100 px-1 rounded">demo@employer.com</code>, or <code className="bg-yellow-100 px-1 rounded">admin@demo.com</code> with password <code className="bg-yellow-100 px-1 rounded">demo123</code> to test login.
                </p>
              </div>
            </div>
          </div>
        </div>
      )}
      
      <main className="flex-grow">
        {/* Database Status Check */}
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-8">
          <DatabaseStatus />
        </div>
        
        <Routes>
          {/* Public Routes */}
          <Route path="/" element={<Home />} />
          <Route path="/about" element={<About />} />
          <Route path="/how-it-works" element={<HowItWorks />} />
          <Route path="/pricing" element={<Pricing />} />
          <Route path="/success-stories" element={<SuccessStories />} />
          <Route 
            path="/login" 
            element={isAuthenticated ? <Navigate to="/dashboard" /> : <Login />} 
          />
          <Route 
            path="/register" 
            element={isAuthenticated ? <Navigate to="/dashboard" /> : <Register />} 
          />
          <Route 
            path="/forgot-password" 
            element={isAuthenticated ? <Navigate to="/dashboard" /> : <ForgotPassword />} 
          />

          {/* Legal Routes */}
          <Route path="/terms-and-conditions" element={<TermsAndConditions />} />
          <Route path="/privacy-policy" element={<PrivacyPolicy />} />
          <Route path="/terms-of-service" element={<TermsOfService />} />
          <Route path="/cookies-policy" element={<CookiesPolicy />} />

          {/* Support Routes */}
          <Route path="/help" element={<HelpCenter />} />
          <Route path="/contact" element={<ContactUs />} />

          {/* Protected Routes */}
          <Route path="/dashboard" element={
            <ProtectedRoute>
              {profile?.user_type === 'worker' && <WorkerDashboard />}
              {profile?.user_type === 'employer' && <EmployerDashboard />}
              {profile?.user_type === 'admin' && <AdminDashboard />}
              {!profile?.user_type && (
                <div className="min-h-screen flex items-center justify-center">
                  <div className="text-center">
                    <LoadingSpinner size="lg" />
                    <p className="mt-4 text-gray-600">Loading your dashboard...</p>
                  </div>
                </div>
              )}
            </ProtectedRoute>
          } />

          {/* Worker Routes */}
          <Route path="/tasks" element={
            <ProtectedRoute allowedRoles={['worker']}>
              <TaskBrowser />
            </ProtectedRoute>
          } />
          <Route path="/tasks/:id" element={
            <ProtectedRoute allowedRoles={['worker']}>
              <TaskDetail />
            </ProtectedRoute>
          } />
          <Route path="/my-submissions" element={
            <ProtectedRoute allowedRoles={['worker']}>
              <MySubmissions />
            </ProtectedRoute>
          } />

          {/* Employer Routes */}
          <Route path="/create-task" element={
            <ProtectedRoute allowedRoles={['employer']}>
              <CreateTask />
            </ProtectedRoute>
          } />
          <Route path="/my-tasks" element={
            <ProtectedRoute allowedRoles={['employer']}>
              <MyTasks />
            </ProtectedRoute>
          } />
          <Route path="/review-submissions" element={
            <ProtectedRoute allowedRoles={['employer']}>
              <ReviewSubmissions />
            </ProtectedRoute>
          } />

          {/* Shared Protected Routes */}
          <Route path="/wallet" element={
            <ProtectedRoute>
              <Wallet />
            </ProtectedRoute>
          } />
          <Route path="/profile" element={
            <ProtectedRoute>
              <Profile />
            </ProtectedRoute>
          } />
          <Route path="/settings" element={
            <ProtectedRoute>
              <Settings />
            </ProtectedRoute>
          } />

          {/* Admin Routes */}
          <Route path="/admin/users" element={
            <ProtectedRoute allowedRoles={['admin']}>
              <UserManagement />
            </ProtectedRoute>
          } />
          <Route path="/admin/tasks" element={
            <ProtectedRoute allowedRoles={['admin']}>
              <TaskManagement />
            </ProtectedRoute>
          } />
          <Route path="/admin/payments" element={
            <ProtectedRoute allowedRoles={['admin']}>
              <PaymentManagement />
            </ProtectedRoute>
          } />

          {/* Catch all route */}
          <Route path="*" element={<Navigate to="/" />} />
        </Routes>
      </main>

      <Footer />
      <MobileNav />
      <AuthDebug />
      
      {/* Toast Notifications */}
      <Toaster
        position="top-right"
        toastOptions={{
          duration: 4000,
          style: {
            background: '#363636',
            color: '#fff',
          },
          success: {
            style: {
              background: '#10b981',
            },
          },
          error: {
            style: {
              background: '#ef4444',
            },
          },
        }}
      />
    </div>
  );
}

export default App;
